import scala.util.Try

object MergeSort {

  def main(args: Array[String]): Unit = {
    // Get user input array
    val input = readIntArray()

    // Sort the input array using merge sort algorithm
    val sortedArray = mergeSort(input)

    // Output the sorted array
    println("Sorted array:")
    sortedArray.foreach(println)
  }

  /**
   * Reads an array of integers from user input
   * @return the array of integers
   */
  def readIntArray(): Array[Int] = {
    println("Enter an array of integers (separated by space):")
    val input = scala.io.StdIn.readLine().split("\\s+")
    Try(input.map(_.toInt)).getOrElse(Array.emptyIntArray)
  }

  /**
   * Sorts an array of integers using merge sort algorithm
   * @param array the array of integers to be sorted
   * @return the sorted array of integers
   */
  def mergeSort(array: Array[Int]): Array[Int] = {
    if (array.length > 1) {
      val mid = array.length / 2
      val leftArray = array.slice(0, mid)
      val rightArray = array.slice(mid, array.length)

      val sortedLeftArray = mergeSort(leftArray)
      val sortedRightArray = mergeSort(rightArray)

      merge(sortedLeftArray, sortedRightArray)
    } else {
      array
    }
  }

  /**
   * Merges two arrays of integers into a single array in ascending order
   * @param leftArray the first array of integers
   * @param rightArray the second array of integers
   * @return the merged array of integers
   */
  def merge(leftArray: Array[Int], rightArray: Array[Int]): Array[Int] = {
    var I = 0
    var j = 0
    val result = new Array[Int](leftArray.length + rightArray.length)

    for (k <- result.indices) {
      if (i >= leftArray.length) {
        result(k) = rightArray(j)
        j += 1
      } else if (j >= rightArray.length || leftArray(i) <= rightArray(j)) {
        result(k) = leftArray(i)
        I += 1
      } else {
        result(k) = rightArray(j)
        j += 1
      }
    }

    result
  }
}
```

