# Binary Search Tree in Python

class Node:
    '''
    A class to represent a node in a binary search tree
    '''

    def __init__(self, value):
        self.value = value
        self.left_child = None
        self.right_child = None

class BinarySearchTree:
    '''
    A class to represent a binary search tree
    '''

    def __init__(self):
        self.root = None

    def insert(self, value):
        '''
        A method to insert a value into the binary search tree
        '''
        if self.root is None:
            self.root = Node(value)
        else:
            self._insert(value, self.root)

    def _insert(self, value, current_node):
        if value < current_node.value:
            if current_node.left_child is None:
                current_node.left_child = Node(value)
            else:
                self._insert(value, current_node.left_child)
        elif value > current_node.value:
            if current_node.right_child is None:
                current_node.right_child = Node(value)
            else:
                self._insert(value, current_node.right_child)
        else:
            print("Value is already in the tree.")

    def search(self, value):
        '''
        A method to search for a value in the binary search tree.
        Returns "Found" if the value is in the tree and "Not found" otherwise.
        '''
        if self.root is None:
            return "Not found"
        else:
            return self._search(value, self.root)

    def _search(self, value, current_node):
        if value == current_node.value:
            return "Found"
        elif value < current_node.value and current_node.left_child is not None:
            return self._search(value, current_node.left_child)
        elif value > current_node.value and current_node.right_child is not None:
            return self._search(value, current_node.right_child)
        else:
            return "Not found"

