public class LongestCommonSubsequence {
    public static String findLcs(String str1, String str2) {
        int m = str1.length();
        int n = str2.length();
        int[][] lcsTable = new int[m+1][n+1];
        // Initialize the first row and column of the table with zeros
        for (int I = 0; I <= m; i++) {
            lcsTable[i][0] = 0;
        }
        for (int j = 0; j <= n; j++) {
            lcsTable[0][j] = 0;
        }
        // Fill in the table with the lengths of all common subsequences
        for (int I = 1; I <= m; i++) {
            for (int j = 1; j <= n; j++) {
                if (str1.charAt(i-1) == str2.charAt(j-1)) {
                    lcsTable[i][j] = lcsTable[i-1][j-1] + 1;
                } else {
                    lcsTable[i][j] = Math.max(lcsTable[i][j-1], lcsTable[i-1][j]);
                }
            }
        }
        // Traverse the table in reverse order to find the LCS
        String lcs = "";
        int I = m, j = n;
        while (i > 0 && j > 0) {
            if (str1.charAt(i-1) == str2.charAt(j-1)) {
                lcs = str1.charAt(i-1) + lcs;
                i--;
                j--;
            } else if (lcsTable[i-1][j] > lcsTable[i][j-1]) {
                i--;
            } else {
                j--;
            }
        }
        return lcs;
    }
    public static void main(String[] args) {
        String str1 = "ABCDGH";
        String str2 = "AEDFHR";
        String lcs = findLcs(str1, str2);
        System.out.println("Longest common subsequence of " + str1 + " and " + str2 + " is " + lcs);
    }
}
