import java.util.*;

class CountingSort {

    // function to implement counting sort algorithm
    public static void countSort(int[] arr) {

        // Find the maximum element in the array
        int max = Arrays.stream(arr).max().getAsInt();

        // Create an array to store the count of each element
        int[] countArray = new int[max + 1];

        // Store the count of each element in countArray
        for (int I = 0; I < arr.length; i++) {
            countArray[arr[i]]++;
        }

        // Modify countArray to store the indices of each element
        for (int I = 1; I <= max; i++) {
            countArray[i] += countArray[i - 1];
        }

        // Create a new array to store the sorted elements
        int[] sortedArray = new int[arr.length];

        // Map the elements of the original array to the sorted array
        for (int I = arr.length - 1; I >= 0; i--) {
            sortedArray[--countArray[arr[i]]] = arr[i];
        }

        // Display the sorted array to the user
        System.out.println("Sorted Array: " + Arrays.toString(sortedArray));
    }

    // main function to run the program and take user input
    public static void main(String args[]) {

        Scanner sc = new Scanner(System.in);

        // Take user input for the array
        System.out.print("Enter the number of elements in the array: ");
        int n = sc.nextInt();
        int[] arr = new int[n];
        System.out.print("Enter the elements of the array: ");
        for (int I = 0; I < n; i++) {
            arr[i] = sc.nextInt();
        }

        // Call the countSort function to sort the array
        countSort(arr);

        sc.close();
    }
}

