3. Set up the `SpeechSynthesizer` and its delegate, and implement the speech generation process:

```
let synthesizer = AVSpeechSynthesizer()

func speak(_ string: String) {
    let utterance = AVSpeechUtterance(string: string)
    utterance.rate = AVSpeechUtteranceMinimumSpeechRate + ((AVSpeechUtteranceMaximumSpeechRate - AVSpeechUtteranceMinimumSpeechRate) * rateSlider.floatValue)
    utterance.pitchMultiplier = pitchSlider.floatValue
    statusLabel.stringValue = "Speaking..."
    synthesizer.speak(utterance)
}

