    for (int I = 0; I < 26; i++) {
      if (!letters[i]){
        isPangram = false;
        break;
      }
    }
    if (isPangram) {
      System.out.println(str + " is a pangram.");
    } else {
      System.out.println(str + " is not a pangram.");
    }
  }
}

