Here is a complete implementation of a singly linked list in Swift:

```
class LinkedListNode<T> {
    var value: T
    var nextNode: LinkedListNode<T>?

    init(value: T, nextNode: LinkedListNode<T>? = nil) {
        self.value = value
        self.nextNode = nextNode
    }
}

class LinkedList<T> {
    var head: LinkedListNode<T>?

    // Add a value to the list at a specified index
    func add(atIndex index: Int, value: T) {
        if index == 0 {
            self.head = LinkedListNode(value: value, nextNode: self.head)
        } else {
            var currentNode = self.head
            for I in 0..<index - 1 {
                currentNode = currentNode?.nextNode
                if currentNode == nil {
                    return
                }
            }
            let newNode = LinkedListNode(value: value, nextNode: currentNode?.nextNode)
            currentNode?.nextNode = newNode
        }
    }

    // Remove a value from the list at a specified index
    func remove(atIndex index: Int) {
        if index == 0 {
            self.head = self.head?.nextNode
        } else {
            var currentNode = self.head
            for I in 0..<index - 1 {
                currentNode = currentNode?.nextNode
                if currentNode == nil {
                    return
                }
            }
            currentNode?.nextNode = currentNode?.nextNode?.nextNode
        }
    }

    // Get the value in the list at a specified index
    func get(atIndex index: Int) -> T? {
        var currentNode = self.head
        for I in 0..<index {
            currentNode = currentNode?.nextNode
            if currentNode == nil {
                return nil
            }
        }
        return currentNode?.value
    }

    // Get the number of values in the list
    func count() -> Int {
        var currentNode = self.head
        var count = 0
        while currentNode != nil {
            count += 1
            currentNode = currentNode?.nextNode
        }
        return count
    }
}

// Testing
let list = LinkedList<Int>()
list.add(atIndex: 0, value: 1)
list.add(atIndex: 1, value: 2)
list.add(atIndex: 2, value: 3)
print(list.get(atIndex: 1)) // Output: Optional(2)
list.remove(atIndex: 1)
print(list.get(atIndex: 1)) // Output: Optional(3)
print(list.count()) // Output: 2
```

This implementation creates a generic `LinkedListNode` class with a value property and a link to the next node. The singly linked list `LinkedList` class has a head property that points to the first node in the list.

The `add(atIndex:)` method adds a new node with the specified value at the specified index in the list. If the index is 0, the new node becomes the head of the list. Otherwise, the method traverses the list until it reaches the node before the specified index, and then inserts the new node after that node.

The `remove(atIndex:)` method removes the node at the specified index from the list. If the index is 0, the head of the list is updated to point to the second node. Otherwise, the method traverses the list to the node before the specified index, and updates its `next` link to skip over the node at the specified index.

The `get(atIndex:)` method returns the value of the node at the specified index in the list. The method traverses the list from the head until it reaches the node at the specified index.

The `count()` method returns the number of nodes in the list. The method traverses the list from the head, counting each node as it goes.

To test the implementation, we create a new `LinkedList` object and add some values to it. We then get the value at a specified index, remove a node, get the value at the same index again, and count the number of nodes in the list.

