    $dbh = new PDO($dsn, $username, $password);
    $dbh->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);
} catch (PDOException $e) {
    die("Error: " . $e->getMessage());
}

// Open CSV file
if (($handle = fopen($csv_file, "r")) !== FALSE) {
    // Loop through rows in CSV file
    while (($data = fgetcsv($handle, 1000, ",")) !== FALSE) {
        // Sanitize and validate data
        $name = filter_var(trim($data[0]), FILTER_SANITIZE_STRING);
        $email = filter_var(trim($data[1]), FILTER_VALIDATE_EMAIL);
        if ($name === "" || $email === false) {
            // Invalid data, skip this row
            continue;
        }
        // Insert data into database
        try {
            $stmt = $dbh->prepare("INSERT INTO users (name, email) VALUES (?, ?)");
            $stmt->bindParam(1, $name);
            $stmt->bindParam(2, $email);
            $stmt->execute();
        } catch (PDOException $e) {
            // Log error
            error_log("Error: " . $e->getMessage());
            // Handle error (e.g. Skip row, stop import)
        }
    }
    fclose($handle);
}

// Close database connection
$dbh = null;

